import pdfWorkerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url';

// Above this, rendering every page to a canvas in the main thread starts to
// feel like it's hung the tab — reject early with a clear reason instead.
export const MAX_PAGES = 60;
export const MAX_BYTES = 60 * 1024 * 1024;

// pdfjs-dist is ~500kB — imported dynamically so it's only downloaded once a
// PDF is actually picked, not just from visiting the page.
let workerConfigured = false;
async function loadPdfjs() {
  const pdfjsLib = await import('pdfjs-dist');
  if (!workerConfigured) {
    pdfjsLib.GlobalWorkerOptions.workerSrc = pdfWorkerUrl;
    workerConfigured = true;
  }
  return pdfjsLib;
}

export interface PdfPageImage {
  pageNumber: number;
  blob: Blob;
  width: number;
  height: number;
}

export interface ConvertProgress {
  page: number;
  total: number;
}

export interface ConvertOptions {
  /** Render scale relative to the PDF's own 72dpi page size — 2 ≈ 144dpi. */
  scale: number;
  /** JPEG quality, 1-100. */
  quality: number;
  /** Which pages to render, in order — omit (or pass an empty array) to render all of them. */
  pages?: number[];
  onProgress?: (progress: ConvertProgress) => void;
}

/** Reads just a PDF's page count without rendering anything — cheap enough to call
 * as soon as a file is picked, so the UI can offer a page-range field right away. */
export async function getPdfPageCount(file: File): Promise<number> {
  const pdfjsLib = await loadPdfjs();
  const buffer = await file.arrayBuffer();
  const loadingTask = pdfjsLib.getDocument({ data: buffer });
  const pdf = await loadingTask.promise;
  const count = pdf.numPages;
  await loadingTask.destroy();
  return count;
}

/** Parses a page-range string like "1-5, 8, 10-12" into a sorted, deduped list of page
 * numbers clamped to [1, totalPages]. An empty/blank input means "every page". Tokens
 * that are out of range or unparseable are silently dropped. */
export function parsePageRange(input: string, totalPages: number): number[] {
  const trimmed = input.trim();
  if (!trimmed) return Array.from({ length: totalPages }, (_, i) => i + 1);

  const pages = new Set<number>();
  for (const rawToken of trimmed.split(',')) {
    const token = rawToken.trim();
    if (!token) continue;

    const rangeMatch = token.match(/^(\d+)\s*-\s*(\d+)$/);
    if (rangeMatch) {
      let start = Number(rangeMatch[1]);
      let end = Number(rangeMatch[2]);
      if (start > end) [start, end] = [end, start];
      for (let p = Math.max(1, start); p <= Math.min(totalPages, end); p++) pages.add(p);
      continue;
    }

    if (/^\d+$/.test(token)) {
      const p = Number(token);
      if (p >= 1 && p <= totalPages) pages.add(p);
    }
  }

  return Array.from(pages).sort((a, b) => a - b);
}

/** Renders the given (or all) pages of a PDF to a JPEG blob each, entirely in the browser. */
export async function convertPdfToImages(file: File, { scale, quality, pages, onProgress }: ConvertOptions): Promise<PdfPageImage[]> {
  const pdfjsLib = await loadPdfjs();
  const buffer = await file.arrayBuffer();
  // getDocument() returns a loading task, not the document itself — .destroy() (which
  // frees the worker-side document/resources) lives on the task, not on the resolved
  // PDFDocumentProxy from .promise.
  const loadingTask = pdfjsLib.getDocument({ data: buffer });
  const pdf = await loadingTask.promise;

  const pageNumbers = pages && pages.length > 0 ? pages : Array.from({ length: pdf.numPages }, (_, i) => i + 1);

  if (pageNumbers.length > MAX_PAGES) {
    const count = pageNumbers.length;
    await loadingTask.destroy();
    throw new Error(`That's ${count} pages — the limit is ${MAX_PAGES} pages per conversion.`);
  }

  const q = Math.min(1, Math.max(0.01, quality / 100));
  const results: PdfPageImage[] = [];

  for (let i = 0; i < pageNumbers.length; i++) {
    const pageNumber = pageNumbers[i];
    onProgress?.({ page: i + 1, total: pageNumbers.length });

    const page = await pdf.getPage(pageNumber);
    const viewport = page.getViewport({ scale });

    const canvas = document.createElement('canvas');
    canvas.width = Math.ceil(viewport.width);
    canvas.height = Math.ceil(viewport.height);
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('Canvas is not supported in this browser');

    // JPEG has no alpha channel — fill white first so transparent PDF regions render as
    // white paper instead of black.
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    await page.render({ canvas, viewport }).promise;

    const blob = await new Promise<Blob>((resolve, reject) => {
      canvas.toBlob((b) => (b ? resolve(b) : reject(new Error('Failed to encode page as JPEG'))), 'image/jpeg', q);
    });

    results.push({ pageNumber, blob, width: canvas.width, height: canvas.height });
    page.cleanup();
  }

  await loadingTask.destroy();
  return results;
}

/** Zips converted pages into a single downloadable blob — built in memory, never uploaded anywhere. */
export async function buildImagesZip(images: PdfPageImage[], baseName: string): Promise<Blob> {
  const { default: JSZip } = await import('jszip');
  const zip = new JSZip();
  const padLength = String(images.length).length;
  for (const { pageNumber, blob } of images) {
    const num = String(pageNumber).padStart(padLength, '0');
    zip.file(`${baseName}-page-${num}.jpg`, blob);
  }
  return zip.generateAsync({ type: 'blob' });
}
